import { createRequire } from 'node:module'
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`
const require = createRequire(`${runtime}/package.json`)
const { chromium } = require('playwright')
const config = await import('node:fs/promises').then(fs => fs.readFile(`${runtime}/linux.json`, 'utf8')).then(JSON.parse)
process.env.DISPLAY ||= ':' + (await import('node:fs/promises').then(fs => fs.readFile('/home/runner/work/_temp/omgithub-runtime/display', 'utf8'))).trim()
const browser = await chromium.launch(config.browser.launchOptions)
for (const viewport of [{ name: 'desktop', width: 1440, height: 900 }, { name: 'mobile', width: 390, height: 844 }]) {
  const page = await browser.newPage({ viewport })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push(m.text()) })
  await page.goto('http://localhost:3002/', { waitUntil: 'load' })
  await page.locator('#play').click()
  await page.waitForTimeout(500)
  const hud = await page.locator('#hud').evaluate(e => getComputedStyle(e).display)
  const ammoBefore = await page.locator('#ammo').textContent()
  if (viewport.name === 'mobile') {
