  } else {
    await page.keyboard.press('Space')
  }
  await page.waitForTimeout(100)
  const ammoAfter = await page.locator('#ammo').textContent()
  const controls = viewport.name === 'mobile' ? await page.locator('.mobile-controls').evaluate(e => getComputedStyle(e).display) : 'desktop keyboard/mouse'
