node --input-type=module <<'EOF'
import { createRequire } from 'node:module'
import { readFile } from 'node:fs/promises'
const runtime = `${process.env.HOME}/.local/share/omgithub-playwright`
const require = createRequire(`${runtime}/package.json`)
const { chromium } = require('playwright')
const config = JSON.parse(await readFile(`${runtime}/linux.json`, 'utf8'))
process.env.DISPLAY ||= ':' + (await readFile(`${runtime}/display`, 'utf8')).trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
const errors = []
page.on('pageerror', e => errors.push(e.message))
await page.goto('http://localhost:3002/', { waitUntil: 'load' })
await page.locator('#play').click()
await page.waitForTimeout(300)
const ui = await page.evaluate(() => {
 const rect = s => { const r=document.querySelector(s).getBoundingClientRect();return {top:Math.round(r.top),bottom:Math.round(r.bottom),left:Math.round(r.left),right:Math.round(r.right)} }
 return {hud:getComputedStyle(document.querySelector('#hud')).display, controls:getComputedStyle(document.querySelector('.mobile-controls')).display, bottomright:rect('.bottomright'), fire:rect('.fire'), reload:rect('.reload'), ammo:document.querySelector('#ammo').textContent}
})
await page.locator('#fire').dispatchEvent('pointerdown', { pointerId: 7, pointerType: 'touch', isPrimary: true, button: 0 })
await page.waitForTimeout(120)
ui.ammoAfterFire = await page.locator('#ammo').textContent()
await page.locator('#reload').dispatchEvent('pointerdown', { pointerId: 8, pointerType: 'touch', isPrimary: true, button: 0 })
await page.waitForTimeout(1450)
ui.ammoAfterReload = await page.locator('#ammo').textContent()
await page.screenshot({path:'/tmp/opencode/ironfront-final/active-mobile.png'})
console.log(JSON.stringify({ui, errors}))
await browser.close()
EOF

